const fetch = require('node-fetch');

async function test() {
  const baseUrl = 'http://localhost:3000';

  // Start server
  const { spawn } = require('child_process');
  const server = spawn('node', ['server.js']);

  // Wait for server to start
  await new Promise(r => setTimeout(r, 2000));

  try {
    // Test health endpoint
    let res = await fetch(`${baseUrl}/api/health`);
    console.log('✓ Health check:', res.status);

    // Test sign in
    res = await fetch(`${baseUrl}/api/signin`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ 
        email: 'avery@dropline.test', 
        password: 'password123' 
      })
    });
    const signInData = await res.json();
    console.log('✓ Sign in:', res.status, signInData.account?.name);

    const token = signInData.token;

    // Test get game
    res = await fetch(`${baseUrl}/api/game`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const gameData = await res.json();
    console.log('✓ Get game:', res.status, 'Scores:', gameData.game?.redWins, gameData.game?.yellowWins, gameData.game?.draws);

    // Test make move
    res = await fetch(`${baseUrl}/api/move`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({
        column: 4,
        operationId: `test-${Date.now()}`,
        expectedRevision: gameData.game.revision
      })
    });
    const moveData = await res.json();
    console.log('✓ Make move:', res.status, 'New player:', moveData.game?.currentPlayer);

    // Test get archives
    res = await fetch(`${baseUrl}/api/archives`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const archivesData = await res.json();
    console.log('✓ Get archives:', res.status, 'Count:', archivesData.total);

    console.log('\n✅ All basic tests passed!');
  } catch (err) {
    console.error('❌ Test failed:', err.message);
  } finally {
    server.kill();
    process.exit(0);
  }
}

test();
EOF

